local UICommonChestUsePopUpDialog = Class("UICommonChestUsePopUpDialog")

function UICommonChestUsePopUpDialog:__init()
    self._goodsVo = nil
    self._stack = 0
    self._allGift= {}
    self._useNum = 1
end

function UICommonChestUsePopUpDialog:__delete()
    self._goodsVo = nil
    self._stack = nil
    self._allGift = nil
    self._useNum = 0
end

function UICommonChestUsePopUpDialog:Awake()
    SetButtonAction(self.BtnClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.BtnAdd, Bind(self, self.OnAdd))
    SetButtonAction(self.BtnReduce, Bind(self, self.OnDel))
    SetButtonAction(self.EmptyClose, Bind(self, self.OnBtnClose))
    SetButtonAction(self.FontStyleButton, Bind(self, self.OnBtnUse))

    self.Slider.onValueChanged:AddListener(function(num)
        self._useNum = checkInt(self._stack * num)
        if self._useNum > self._stack then
            self._useNum = self._stack
        elseif self._useNum <= 0 then
            self._useNum = 0
        end
        self:FillUseInfo()
    end)
end

function UICommonChestUsePopUpDialog:OnBtnUse()
    if self._useNum <= 0 then
        GameUtils.Toast(localize("最少使用一个"))
        return
    end

    local goodsTypeMap = {}
    for _, giftData in ipairs(self._allGift) do
        local goodsId   = checkInt(giftData.id)
        local goodsVo   = goodsConfMgr:GetGoodsVoById(goodsId)
        local goodsType = checkInt(goodsVo.type)
        goodsTypeMap[tostring(goodsType)] = true
    end
    for goodsType, _ in pairs(goodsTypeMap) do
        local backpackVo = GoodsUtils.GetBasicPacketByGoodsType(goodsType)
        local isFilled   = backpackVo and GoodsUtils.IsPacketFilledById(backpackVo.id) or false
        if isFilled then
            GameUtils.Toast(localize("_name_背包已满，请前往清理", {_name_ = backpackVo.name}))
            return 
        end
    end

    -- local isFilled, packetVo = GoodsUtils.IsPacketFilled()
    -- if isFilled then
    --     GameUtils.Toast(localize("_name_背包已满，请前往清理", {_name_ = packetVo.name}))
    --     return false
    -- end

    GameUtils.Request(Interfaces.BackpackUse, {
        goodsId = self._goodsVo.id, num = self._useNum
    }, function(request, response)
        if checkNumber(response.errCode)  == 0 then
            ---成功了
            local data = checkTable(response.data)
            local rewards = checkTable(data.rewards)
            local t = {}
            table.insert(t, {goodsId = self._goodsVo.id, num = -self._useNum, playerItemId = self.equipId})
            GoodsUtils.DrawRewards(t, true)
            if #rewards > 0 then
                GoodsUtils.DrawRewards(rewards, true)
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = data.rewards }
                        }
                )
            end
            UIModule.CloseDialog(self.controller)
        end
    end)
end

function UICommonChestUsePopUpDialog:OnAdd()
    if self._useNum >= self._stack then
        return
    end

    self._useNum = self._useNum + 1
    self:FillUseInfo()
end

function UICommonChestUsePopUpDialog:OnDel()
    if self._useNum <= 0 then
        return
    end
    self._useNum = self._useNum - 1
    self:FillUseInfo()
end

function UICommonChestUsePopUpDialog:OnBtnClose()
    UIModule.CloseDialog(self.controller)
end

function UICommonChestUsePopUpDialog:FillSelf()
    self:FillBoxGoodsInfo()
    self:FillRewards()
    self:FillUseInfo()
end

function UICommonChestUsePopUpDialog:FillUseInfo()
    CfUtils.FillText(self.TextNumber, self._useNum)
    self.Slider.value = checkNumber(self._useNum) / checkNumber(self._stack)
end

function UICommonChestUsePopUpDialog:FillBoxGoodsInfo()
    CfUtils.FillImage(self.ImgQuality, GoodsUtils.GetGoodsBackgroundByQualityType(self._goodsVo.quality))
    CfUtils.FillImage(self.ImgChestIcon, goodsConfMgr:GetPhotoPathById(self._goodsVo.id))
    CfUtils.FillText(self.TxtName, self._goodsVo.name)
    CfUtils.FillText(self.TxtState, self._goodsVo.description)
    CfUtils.FillText(self.TxtPossessNum, self._stack)

    CfUtils.FillText(self.TextNumberLeft, 1)
    CfUtils.FillText(self.TextNumberRight, self._stack)
end

function UICommonChestUsePopUpDialog:FillRewards()
    self._allGift = {}
    local _t = {}
    for _, vo in ipairs(GoodsUtils.GetGoodsGroupVosById(self._goodsVo.id)) do
        local v = vo.id
        local goodsVo = GoodsUtils.GetGoodsVoById(vo.reward)
        if not _t[checkString(goodsVo.id)] then
            _t[checkString(goodsVo.id)] = {
                id = goodsVo.id,
                showMin = 999999,
                showMax = 0,
                sortKey = checkNumber(v)
            }
        end

        if checkNumber(vo.minNum) < _t[checkString(goodsVo.id)].showMin then
            _t[checkString(goodsVo.id)].showMin = checkNumber(vo.minNum)
        end
        if checkNumber(vo.maxNum) > _t[checkString(goodsVo.id)].showMax then
            _t[checkString(goodsVo.id)].showMax = checkNumber(vo.maxNum)
        end
    end

    for k, v in pairs(_t) do
        table.insert(self._allGift, v)
    end

    table.sort(self._allGift, function(a, b)
        return checkNumber(a.sortKey) < checkNumber(b.sortKey)
    end)

    self.ListView:InitGridView(#self._allGift, Bind(self, self.OnGetItemByIndex))
end

function UICommonChestUsePopUpDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("GoodPar")
    local go = cell.transform:Find("GoodNode")
    local data = self._allGift[index + 1]

    local str = data.showMin.."~"..data.showMax
    if checkNumber(data.showMax) == checkNumber(data.showMin) then
        str =  checkNumber(data.showMax)
    end
    CfUtils.RefeshGoodGo2(go, data.id, str, nil, nil, function()
        local goodsVo = goodsConfMgr:GetGoodsVoById(data.id)
        GameUtils.ShowCommonTipsBoard(go, goodsVo.name, goodsVo.desc, goodsVo.quality, goodsVo.id)
    end)
    return cell
end

function UICommonChestUsePopUpDialog:OnInitialize()
    return CoWaitDo(function()
        local argument = self.controller.Argument.parameters
        if not argument then
            return
        end
        self._goodsVo = (argument.goodsVo)   
        self._stack = checkNumber(argument.stack)   
        if isNull(self._goodsVo) then
            return
        end

        self:FillSelf()
    end)
end

function UICommonChestUsePopUpDialog:OnFinalize()
    return CoWaitDo(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end)
end

return UICommonChestUsePopUpDialog
